const assert = require("node:assert/strict");
const { canShip } = require("./shipping");

const cases = [
  {
    name: "positive: ready and not held",
    order: { id: "A-100", status: "ready", hold: false },
    expected: true
  },
  {
    name: "negative: ready but held",
    order: { id: "A-101", status: "ready", hold: true },
    expected: false
  },
  {
    name: "changed input: packed instead of ready",
    order: { id: "A-100", status: "packed", hold: false },
    expected: false
  }
];

let failures = 0;

for (const testCase of cases) {
  const actual = canShip(testCase.order);
  try {
    assert.strictEqual(actual, testCase.expected);
    console.log(`PASS: ${testCase.name}`);
  } catch {
    failures += 1;
    console.log(`FAIL: ${testCase.name}: expected ${testCase.expected}, got ${actual}`);
  }
}

if (failures !== 0) {
  console.log(`FAILURES: ${failures}`);
  process.exitCode = 1;
} else {
  console.log("PASS: 3 immutable shipping eligibility cases");
}

